import React, { useEffect, useState } from "react";
import { getStore, updStore } from "../stores/Utils";


const ObserveEvent = (input) => {
	const [value, setValue] = useState("");

	const compareEvent = (e) => {
		let lastTimeCallModal = getStore("lastTimeCall_"+input) || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCall_"+input, Date.now()+90);
			if(e.detail.id===input){
				return e.detail.hash;
			}
		}
		return "";
	}

	useEffect(() => {
		
		const setFromEvent = (e) => setValue(compareEvent(e));

		document.addEventListener(input, setFromEvent);
		return () => {
			document.removeEventListener(input, setFromEvent);
		};
	  }, []);

	return value;
};

export default ObserveEvent;





