export const initQry = async (cb) => {
  let bdyq2 = {
      query: "53hvscu362"
  };
  const res = fetchEncryptStream(bdyq2);
  const td = await res;
  if (td && !td.error) {
      let qcb = getStore(qryStore()) || {};
      let updQry = Object.assign({},qcb, td)
      updStore(qryStore(), updQry);
  }
  cb && cb();
};


export const validateTkn = async () =>{
  let Qry_V = getStore(qryStore())?.validateTkn;
  let token = check_cookie_name(tokenNameCookie());
  let tkn2FA = check_cookie_name("F2Atkn");

  if(Qry_V){
    Qry_V.params = {
      tkn:  token,
      tkn2FA
    }
    const resV = fetchEncryptStream(Qry_V);
    const tdV = await resV;
    if (tdV && tdV.userId) {
        initializeBussines(tdV.businessId)
        updStore("profileUser",tdV)
        updStore("isAdmin",tdV.isAdmin);
        updStore("phoneNumberH",tdV.phoneNumber);
        getYearAccBussines(tdV.businessId);
        return 1;
    }
    else if (tdV && tdV.phoneNumber) {
      updStore("businessId",tdV.businessId)
      updStore("phoneNumberC",tdV.phoneNumber);
      updStore("phoneNumberCode",tdV.phoneNumber.slice(tdV.phoneNumber.length-3,tdV.phoneNumber.length));
      openViewCode();
      return 2;
    }

  }
  return null;
}






