import { useState, useEffect } from 'react'
import './App.css'
import loadable from '@loadable/component';

import { DialogHRM_Cmpt, SvgIcon_Cmpt, Toast_Cmpt, LoadingColorSpinner_Cmpt } from './components';
import {FloatingSideMenu_Cmpt} from './features/FloatingSideMenu';
import { 
  init_icons, getStore, routeList, updStore, hasWritePrivilege,
  check_cookie_name, decryptV4, tokenNameCookie, loadUrlByMT, observingDimension
} from './stores/Utils';


import ObserveEvent from "./hooks/observeEvent";

import GoogleSingIn, { initQry, validateTkn } from './services/googleSingIn';


import { Aaccountlist_Cmpt, ParameterizeBG_Cmpt } from './features/CuentasContables';
import { ComprobanteList_Cmpt } from './features/Comprobantes';
import { CollectList_Cmpt, ToPaylist_Cmpt } from './features/Cobros';
import {UserDashboard_Cmpt} from './features/Users';
import { Entrylist_Cmpt } from './features/ComprobanteParametrizados';
import { HashRouter, useRoutes, useLocation } from "react-router-dom";






import './features/CuentasContables/component/dashboard.css';
import { InventoryDashboard_Cmpt } from './features/Inventory';
import {  PayrollDashboard_Cmpt } from './features/Employees';
import { ProvidersDashboard_Cmpt } from './features/ProvidersCustomers';
import { InvoicesDashboard_Cmpt } from './features/Invoices';
import { PayChecksOnFuturesDashboard_Cmpt } from './features/PayChecksOnFuture';
import { FeedfromMobilesDashboard_Cmpt, CategoriesMobileDashboard_Cmpt } from './features/FeedFromMobile';
import { DashboardSerice_Cmpt, CustomerDetail_Cmpt } from './featuresMobile/DashBoardServices';
import { AmznInvDashboard_Cmpt } from './features/AmznInventory';
import { DepositSummaryDashboard_Cmpt } from './features/depositSummary';


const QrSingIn = loadable(() => import("./services/QrSingIn")); 


const ComprobanteList = ComprobanteList_Cmpt();
const Aaccountlist = Aaccountlist_Cmpt()
const InventoryDashboard = InventoryDashboard_Cmpt()

const CobroList = CollectList_Cmpt()
const ToPaylist = ToPaylist_Cmpt()

const UserDashboard = UserDashboard_Cmpt();

const Entrylist = Entrylist_Cmpt();

const EmployeesDashboard = PayrollDashboard_Cmpt();

const DepositSummaryDashboard = DepositSummaryDashboard_Cmpt();


const ProvidersDashboard = ProvidersDashboard_Cmpt();

const PayChecksOnFuturesDashboard = PayChecksOnFuturesDashboard_Cmpt();


const DialogHRM = DialogHRM_Cmpt()

const FloatingSideMenu = FloatingSideMenu_Cmpt()

const ParameterizeBG = ParameterizeBG_Cmpt()


const Toast = Toast_Cmpt();


const InvoicesDashboard = InvoicesDashboard_Cmpt()


const AmznInvDashboard = AmznInvDashboard_Cmpt()



const FeedfromMobilesDashboard = FeedfromMobilesDashboard_Cmpt();


const CategoriesMobileDashboard = CategoriesMobileDashboard_Cmpt();


const LoadingColorSpinner = LoadingColorSpinner_Cmpt();


const DashboardSericeMbl = DashboardSerice_Cmpt();

const MovementDetailMbl = CustomerDetail_Cmpt();


const Svg = SvgIcon_Cmpt();

///  


const App = () => {
  const [validated, setValidated] = useState(false)

  const verify = async () =>{
    let h = await validateTkn(()=>{});
    if(h){
      setValidated(true)
    }
  }

  useEffect(() => {

    observingDimension();

    let authToken = check_cookie_name("hrm_access_tkn");
    let dToken = check_cookie_name(tokenNameCookie());
    loadUrlByMT("svgs.json",init_icons);




    if(authToken && dToken && dToken.length>10  && authToken.length>10 ){
      let access_token = authToken?.slice(authToken.toString().length-32, authToken.toString().length-16);  
      access_token = authToken?.slice(0,16);
      let decrypkey = decryptV4(dToken.split(":")[1],access_token);
      updStore("sectionKey",decrypkey);
      initQry(()=>{
        verify();
        
      })
    }else{
      setValidated(true)
    }





    let now = (new Date())
    let YY = now.getFullYear()*1;
    let YY2 = now.getFullYear()*1+1;
    let initDate = (new Date("01/01/"+YY)).getTime(); 
    let lastDate = (new Date("01/01/"+YY2)).getTime() - 10;

    let mnth = now.getMonth() +1;
    let dt = (new Date((now.getMonth()+1)+"/01/"+now.getFullYear()));
    let initDateMP = dt.getTime();
		let lastDateMP = dt.setMonth(mnth) - 600;

    updStore("date_range_option","allYear");
    updStore("movement_type","expenses");
    updStore("date_current_year", now.getFullYear() )
    updStore("date_range_comps", {initDate,lastDate} )
    updStore("date_range_submayor", {initDate: initDateMP, lastDate: lastDateMP} );
    updStore("modernFontReport",true);
  
    return () => {
      //
    }
  }, [])

	return (
		<div
      theme={"92357239"} 
			style={{ zIndex: 0, overflow: "hidden" }}
			className={"palette_body App light_theme"}>
				<HashRouter>
					<InitCmpt validated={validated} />
          <DialogHRM />
				</HashRouter>
        <Toast />
		</div>
	);
};















function InitCmpt({validated}) {

  const [view, setView] = useState(6)

  const observeComponent = ObserveEvent("dimention_hash");


  let location = useLocation();
 
  
  useEffect(() => {
    setView(routesIndex[location.pathname])

    return () => {
      //
    }
  }, [location.pathname, location.search])
  

 

  let routesIndex = {
    "/accounts":6,
    "/accounting-ledger":7,
    "/collect":14,
    "/pay":14,
    "/users-dashboard":10,
    "/inventory":12,
    "/employees":13,
    "/providers-and-customers":14,
    "/invoices":16,
    "/parameterize-balance":6,
    "/pay-checks-on-future":14,
    "/feed-from-mobile": 8,
    "/categories-mobile": 8,
    "/amzn-inventory":17,
    "/deposits":11
  }




  let profileUser = getStore("profileUser");

 
  
  if(!validated){
    return  (
      <div  className={"loading_app"}>
        		<LoadingColorSpinner stroke={"#646cff"} size={94} strokeW={3}/>
			
      </div>
    
    )
  }


  if(location.pathname === "/login-qr"){
    return  (
      <div>
          <RoutesWL />
      </div>
    )
  }




  if(getStore("isMobile")){
    return  (
      <div className={"mobile_style"}>
        {profileUser?.userId ? (
          <div>
              <RoutesMb />
          </div>

        ):
        <GoogleSingIn />}
      </div>
    )
  }


  return (
    <div >
      {profileUser?.userId ? (
      <div 
        className={"_dsplFlx dashboard formContainer"}
        style={{
          width: "100%",
          "--menu-slide-wd": "242px",
          opacity: 1
        }}
      >
        <FloatingSideMenu  data={routeList()} active={view} updTab={setView}/>
        <div 
          className={"dashboard_body"}
          style={{
            opacity: 1,
            width: "calc(98vw - var(--menu-slide-wd))",
            minHeight: "96vh"
          }}
        >

            <RoutesH />
          
        </div>
      </div>
      ):
      <div>
         <RoutesWL />
      </div>}
     
     
    
    </div>
  )
}

export default App






function RoutesH() {


	return useRoutes([
    { path: "/", element: hasWritePrivilege()?<Aaccountlist />: <ProvidersDashboard />  },
    
    { path: "accounts", element: hasWritePrivilege()?<Aaccountlist />:null },
    { path: "entries", element: hasWritePrivilege()?<Entrylist />:null },
    { path: "accounting-ledger", element: hasWritePrivilege()?<ComprobanteList />:null },
		{ path: "collect", element: <CobroList /> },
    { path: "pay", element: <ToPaylist /> },
    { path: "inventory", element: <InventoryDashboard /> },
    { path: "employees", element: <EmployeesDashboard /> },
    { path: "invoices", element: <InvoicesDashboard /> },
    { path: "providers-and-customers", element: <ProvidersDashboard /> },
    { path: "feed-from-mobile", element: <FeedfromMobilesDashboard /> },
    { path: "categories-mobile", element: <CategoriesMobileDashboard /> },

  
    
    { path: "deposits", element: hasWritePrivilege()?<DepositSummaryDashboard />:null },
    { path: "parameterize-balance", element: hasWritePrivilege()?<ParameterizeBG />:null },
    { path: "pay-checks-on-future", element: hasWritePrivilege()?<PayChecksOnFuturesDashboard />:null },
    
    { path: "users-dashboard", element: getStore("isAdmin")? <UserDashboard />: null },
    { path: "amzn-inventory", element: getStore("isAdmin")? <AmznInvDashboard />: null },
	]);
}




function RoutesMb() {
	return useRoutes([
    { path: "/", element: <DashboardSericeMbl />  },
    { path: "employees", element: <EmployeesDashboard /> },
    { path: "providers-and-customers", element: <ProvidersDashboard /> },
    { path: "movements", element: <DashboardSericeMbl /> },
    { path: "movements/detail", element: <MovementDetailMbl /> },
    { path: "categories-mobile", element: <CategoriesMobileDashboard /> },
	]);
}



function RoutesWL() {
	return useRoutes([
    { path: "/", element: <GoogleSingIn />  },
    { path: "/login-qr", element: <QrSingIn /> },

	]);
}


