import { useState } from "react";
import { SvgIcon_Cmpt } from ".";
import ObserveAttributeEvent from "../hooks/observeEventAttr";
import {  colorTheme, gen16CodeId, hex2rgb, observeTagAttr} from "../stores/Utils";

const Svg = SvgIcon_Cmpt();


export const GrayButton  = ({ clickHandler, label, theme, width, icon, color, inner	 }) => {

	const [obs, set_obs] = useState(1);
	
	
	const updObs =  () => {
		set_obs(gen16CodeId())
	}

	observeTagAttr("color_changed", updObs, null, label)


	const targetNode = document.querySelector('html');
	let light =  targetNode.getAttribute("light-theme");

	if(theme){
		let thmL = light?"light":"dark"
		
		color = colorTheme?.[thmL]?.[theme];
   }

	
	let styleCls = {
		
	}

	if(color){
		let {r, g, b} = hex2rgb(color);
	
		let rgb15 = "rgba(" + [r, g, b].join(",") + ", 0.17 )";
		let rgb27 = "rgba(" + [r, g, b].join(",") + ", 0.21 )";
		let rgb33 = "rgba(" + [r, g, b].join(",") + ", 0.42 )";

		
		styleCls = {
			"--btn_bg_hrm2":rgb15,
			"--btn_bg_hover_hrm2": rgb27,
			"--btn_text_hrm2": color,
			"--btn_border_hrm2": light?color:"transparent"
		}

		if(light){
			styleCls = {
				"--btn_bg_hrm2":rgb15,
				"--btn_bg_hover_hrm2": rgb27,
				"--btn_text_hrm2": color,
				"--btn_border_hrm2": color
			}
		}
	}

	

	if(width)(
		styleCls.width = width
	)

	return (
		<div className=" jaqJnq_hrm1" style={styleCls} >
			<button className={`gHAsFI_hrm1 dqnOfN jUrKkb ${theme}`} onClick={clickHandler}>
				{inner?
				<div style={{padding:"5px 10px 0 0" , cursor: "pointer"}} >
					{inner}
				</div>
				:null}
				{icon?
				<div style={{padding:"5px 10px 0 0" , cursor: "pointer"}} >
					<Svg name={icon} color={"var(--btn_text_hrm2)"}/>
				</div>
				:null}
				<span className=" jaqJnq_hrm1" >
					{label}
				</span>
			</button>
		</div>
	)
}




