export const initQry = async (cb) => {
  let bdyq2 = {
      query: "53hvscu362"
  };
  const res = fetchEncryptStream(bdyq2);
  const td = await res;
  if (td && !td.error) {
      let qcb = getStore(qryStore()) || {};
      let updQry = Object.assign({},qcb, td)
      updStore(qryStore(), updQry);
  }
  cb && cb();
};


export const validateTkn = async (token, cb) =>{
  let Qry_V = getStore(qryStore())?.validateTkn;
  if(Qry_V){
    Qry_V.params = {
      tkn:  token
    }
    const resV = fetchEncryptStream(Qry_V);
    const tdV = await resV;
    if (tdV && tdV.userId) {
        initLibPdf();
        updStore(qryKprofile(),tdV)
        updStore("isAdmin",tdV.isAdmin);
        updStore("hasNotaryAccess",tdV.hasNotaryAccess);
        let accessActivities = [];
        ObjectKeys(tdV.accessActivities).map(kA=>{
          let itm = tdV.accessActivities[kA];
          if(itm.isActive){
            accessActivities.push({id: itm.idCode, label: itm.label});
          }
        })
        updStore("accessActivities",tdV.accessActivities )
        updStore("accessActivitiesDrodDwn",accessActivities )

        // console.log(tdV.accessActivities)
        // console.log(accessActivities)
        callDispatchEvent("dimention_hash");
        callDispatchEvent("app_reload_hash");


    }

  }
  cb && cb();
}




