import  { useEffect, useState } from "react";
import { getStore,  updStore } from "../stores/Utils";


const config = {
	attributes: true, 
	//childList: true, 
	characterData: true
};

const ObserveAttributeEvent = (attr,target) => {
	const [value, setValue] = useState("");

	useEffect(() => {
			
		const observer = new MutationObserver((mutations)=>{
			let lastTimeCallModal = getStore("_last_ObserveAttributeEvent_mutation"+attr) || 0;
			if(Date.now() > lastTimeCallModal){
				updStore("_last_ObserveAttributeEvent_mutation"+attr, Date.now()+160);
				mutations.forEach(mutation => {
				if(mutation.type === "attributes"){
					let mAtr = mutation.attributeName.toString().trim();
					let Attr = attr.toString().trim();
					if(mAtr === Attr){
						const targetNode2 = target || document.querySelector('html');
						let hh = targetNode2.getAttribute(Attr);
						setValue(hh);
					}
				}
				});
			}
		});
		
		const targetNode = target || document.querySelector('html');
		observer.observe(targetNode, config);

	  }, [attr]);

	return value;
};

export default ObserveAttributeEvent;





