import { initializeApp } from 'firebase/app';
import { getFirestore, collection, getDocs, onSnapshot, doc , setDoc, deleteDoc  } from 'firebase/firestore';
import { Base64Decode, updStore, callDispatchAttEvent, deepCompareJSON, getStore,  decryptV4, tokenNameCookie } from './Utils';
import { CloseAllModal,  } from '../components/DialogHRM';
import { initQry, validateTkn } from '../services/googleSingIn';



function fs_cdata() {
    return '';
}

var fb_config = JSON.parse(Base64Decode(fs_cdata()));



const app = initializeApp(fb_config);

const db = getFirestore(app);




  var loginQRData = {}

  var loginQRUnsubscribe = null


  export const snapshotLoginQR = ( _Id, lo)=>{
    if(!loginQRUnsubscribe){
      loginQRUnsubscribe = onSnapshot(doc(db, "loginQR", _Id), (doc) => {
        var s = doc?.data();
      
        if(lo){
        
             
          if(s?.success){
           
            if(!deepCompareJSON(loginQRData[_Id], s)){
              loginQRData[_Id] = s;
              updStore("loginQRPending",false);
              updStore("loginQRSucceed",true);
            
              rmvLQRLink(_Id);

             
                getStore("useNavigate")({
                  pathname: "/"
                });
             
             
            }
          }
          else if(s?.requestID){
            updStore("loginQRPending",true);
          }
          
        }else{
          if(s?.token){
            if(!deepCompareJSON(loginQRData[_Id], s)){
            
              loginQRData[_Id] = s;
              updStore("loginQR",loginQRData);
              ValidateFB(_Id, s);
            }
          }
        }
        callDispatchAttEvent("qr_log");
      });
    }
  }
  


  export const addLQRLink = async ( id, data) =>{
      const docRef =  doc(db, 'loginQR', id);
      setDoc(docRef, data);
  }



export const updLQRLink = (mmK, obj)=>{
  const docRef = doc(db, 'loginQR' , mmK);
  setDoc(docRef,  obj , { merge: true });
}

  export const rmvLQRLink = async ( id) =>{
    const docRef =  doc(db, 'loginQR', id);
    deleteDoc(docRef);
  }



  export const ValidateFB = async (_Id, data) =>{

    let dataK = data;

    let {token,
      access_token,
      credential
      } = dataK;

      
    if(token){
       
          
      let _now = new Date().getTime();
      let _expire = new Date(_now + 60000 * 60 * 24 * 365);
      let ckNm = tokenNameCookie();
      let decrypkey = decryptV4(token.split(":")[1],access_token);
      updStore("sectionKey",decrypkey)
      document.cookie = `${ckNm}=${token}; expires=${_expire}; path=/;g_state = {"i_l":1,"i_p":${_expire}}; hrm_access_tkn = ${credential}`;
      document.cookie = `hrm_access_tkn = ${credential}; expires=${_expire};`;
       

      initQry(async ()=>{
        let vtk = await validateTkn(token);
        if(vtk){
          updLQRLink(_Id, {success:true})
        }
      })

     

  }
}

