export const compareObj2Layer = (item, bkUp) =>{
  let r = 0;
  let data  = [];
  let next  = [];
  if(typeof item === "object"){
    item && ObjectKeys(item).map(k1=>{
      if(typeof item[k1] === "object"){
        ObjectKeys(item[k1]).map(k2=>{
          if(typeof item?.[k1]?.[k2] === "object"){
            next.push({item: item[k1][k2], bkUp: bkUp?.[k1]?.[k2], fld: k1, fld2: k2 });
          }
          else if(item?.[k1]?.[k2]!==bkUp?.[k1]?.[k2]){
            r += 1;
            data.push({item: item?.[k1]?.[k2], bkUp: bkUp?.[k1]?.[k2], fld: k1, fld2: k2 });
          }
        })
      }
      else if(item?.[k1]!==bkUp?.[k1]){
        r += 1;
        data.push({item: item?.[k1], bkUp: bkUp?.[k1], fld: k1 });
      }
    })
  }
  else if(item!==bkUp){
    r = 1;
  }
  return { data, next, r};
}


export const compareObjJSON = (item, bkUp) =>{
    let next = null, r = 0;
    if(typeof item === "object"){
      item && ObjectKeys(item).map(k1=>{
        if(typeof item[k1] === "object"){
          let dply2 = compareObj2Layer(item?.[k1], bkUp?.[k1], k1);
          if(dply2?.data?.length>0){
            r = 1;
          }else  if(dply2?.data?.length>0){
            next = dply2.next;
          }
        }
        else if(item?.[k1]!==bkUp?.[k1]){
          r = 1;
        }
      })
    }
    else if(item!==bkUp){
      r = 1;
    }
    return { next, r};
}


