export const sortByObjectKey = (td, key, order) => {
  let sortedA = td && td.sort((a, b) => {
      let A = a[key];
      let B = b[key];
      if (A < B) {
          return order ? -1 : 1;
      }
      if (A > B) {
          return order ? 1 : -1;
      }
      return 0;
  });
  return sortedA;
}


export const sortByFunc = (td, cb, order) => {
  let sortedA = td && td.sort((a, b) => {
      let A = cb(a);
      let B = cb(b);
      if (A < B) {
          return order ? -1 : 1;
      }
      if (A > B) {
          return order ? 1 : -1;
      }
      return 0;
  });
  return sortedA;
}


