export const getWeekDetailsByDay = (day) =>{
  let dyWS = 0;
  let currentDate = new Date(day);
  let _1dy = 86400000;
  let _1Wk = _1dy * 7;
  let dayOfW2 = currentDate.getDay();
  let dayOfM = currentDate.getDate();
  let Stday;
 
  if(dayOfW2>=dyWS){
    Stday = dayOfM-(dayOfW2-dyWS);
    if(dayOfW2===dyWS){
      Stday = dayOfM;
    }
  }
  else{
    let backDay = 7-(dyWS-dayOfW2);
    Stday = dayOfM-backDay;
  }
  let stWk = (new Date(currentDate.setDate(Stday)));
  stWk.setHours(1);
  stWk.setMinutes(1);
  let endWk = stWk.getTime() + _1Wk - 150000;
  
  return { stWk: Math.floor(stWk.getTime()/100000)*100000 , endWk:Math.floor(endWk/100000)*100000 };
}





var th = ['', ' thousand', ' million', ' billion', ' trillion', ' quadrillion', ' quintillion'];
var dg = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];
var tn = ['ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
var tw = ['twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];

export function num2Word(numString){
    if (numString === '0') {
        return 'Zero' ;
    }
    if (numString === 0) {
        return 'Zero';
    }
    var output = toWords(numString);
    return output;
}


function toWords(s) {
    s = s.toString();
    s = s.replace(/[\, ]/g, '');
    //if (s !== parseFloat(s)) return 'not a number';
    var x = s.indexOf('.');
    if (x === -1) x = s.length;
    if (x > 15) return 'too big';
    var n = s.split('');
    var str = '';
    var sk = 0;
    for (var i = 0; i < x; i++) {
        if ((x - i) % 3 === 2) {
            if (n[i] === '1') {
                str += tn[Number(n[i + 1])] + ' ';
                i++;
                sk = 1;
            } else if (n[i] !== 0) {
                str += tw[n[i] - 2] + ' ';
                sk = 1;
            }
        } else if (n[i] !== 0) {
            str += dg[n[i]] + ' ';
            if ((x - i) % 3 === 0) str += 'hundred ';
            sk = 1;
        }
        if ((x - i) % 3 == 1) {
            if (sk) str += th[(x - i - 1) / 3] + ' ';
            sk = 0;
        }
    }
    if (x !== s.length) {
        var y = s.length;
        str += ('and ');
        for (var i = x + 1; i < y; i++) str += n[i] + '';
        str += '/100';
    }
    return str.replace(/\s+/g, ' ');
}






export const hex2rgb = (hex) => {
  hex = hex.replace('#', '')
  if (hex.length !== 6) {
    hex = modifyHex(hex)
  }
  const r = parseInt(hex.slice(0, 2), 16)
  const g = parseInt(hex.slice(2, 4), 16)
  const b = parseInt(hex.slice(4, 6), 16)
  
  // return {r, g, b} 
  return { r, g, b };
}




function modifyHex(hex) {
  if (hex.length === 4) {
    hex = hex.replace('#', '');
  }
  if (hex.length === 3) {
    hex = hex[0] + hex[0] + hex[1] + hex[1] + hex[2] + hex[2];
  }
  return hex;
}

